// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/factories", wrapper.ListFactories)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/projects", wrapper.ListProjects)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/projects", wrapper.CreateProject)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/projects/{id}/confirm", wrapper.ConfirmProject)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customers", wrapper.ListCustomers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customers", wrapper.CreateCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customers/{id}/confirm", wrapper.ConfirmCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/contracts", wrapper.ListContracts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/contracts", wrapper.CreateContract)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/contracts/{id}", wrapper.GetContract)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/contracts/{id}/audit-valuation", wrapper.AuditContractValuation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/jobs", wrapper.ListJobs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/batches", wrapper.ListBatches)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/batches", wrapper.CreateBatch)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/batches/{id}", wrapper.GetBatch)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/batches/{id}/schedule", wrapper.ScheduleBatch)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/batches/{id}/items", wrapper.ListBatchItems)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/batches/{id}/items", wrapper.ReplaceBatchItems)
	})

	return r
}

